PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS users(id INTEGER PRIMARY KEY AUTOINCREMENT,username TEXT UNIQUE NOT NULL,password_hash TEXT NOT NULL,role TEXT NOT NULL CHECK(role IN('ADMIN','CUSTOMER')),display_name TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sessions(token_hash TEXT PRIMARY KEY,user_id INTEGER NOT NULL REFERENCES users(id),expires_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS resources(id INTEGER PRIMARY KEY AUTOINCREMENT,code TEXT UNIQUE NOT NULL,name TEXT NOT NULL,location TEXT NOT NULL,capacity INTEGER NOT NULL CHECK(capacity>0),hourly_rate REAL NOT NULL CHECK(hourly_rate>=0),active INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS reservations(id INTEGER PRIMARY KEY AUTOINCREMENT,reference TEXT UNIQUE NOT NULL,resource_id INTEGER NOT NULL REFERENCES resources(id),customer_id INTEGER NOT NULL REFERENCES users(id),start_at TEXT NOT NULL,end_at TEXT NOT NULL,attendees INTEGER NOT NULL CHECK(attendees>0),purpose TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'PENDING' CHECK(status IN('PENDING','CONFIRMED','CANCELLED','COMPLETED')),total REAL NOT NULL CHECK(total>=0),created_at TEXT DEFAULT CURRENT_TIMESTAMP,updated_at TEXT DEFAULT CURRENT_TIMESTAMP,CHECK(end_at>start_at));
CREATE INDEX IF NOT EXISTS idx_reservation_overlap ON reservations(resource_id,start_at,end_at,status);
CREATE TABLE IF NOT EXISTS reservation_events(id INTEGER PRIMARY KEY AUTOINCREMENT,reservation_id INTEGER NOT NULL REFERENCES reservations(id),user_id INTEGER NOT NULL REFERENCES users(id),event TEXT NOT NULL,created_at TEXT DEFAULT CURRENT_TIMESTAMP);
